import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, PointLight, Color } = ctx.THREE;

  const group = new Group();

  // 1. Geometry - Aspect ratio matched to 512x320 from spec (1.6)
  const geometry = new PlaneGeometry(3.5, 2.1875);

  // 2. Material with TSL-engineered gradient and subtle accent border
  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.20
  });

  // Color logic using TSL
  const uvNode = uv();
  // Deep surface gradient: near-black (#0b0b10) to ink (#16161d)
  const grad = uvNode.y;
  const baseColor = mix(vec3(0.043, 0.043, 0.063), vec3(0.086, 0.086, 0.114), grad);

  // Accent pinstripe top highlight (#ff2a38)
  const accentLine = smoothstep(0.96, 0.97, uvNode.y).mul(smoothstep(0.99, 0.98, uvNode.y));
  const finalColor = mix(baseColor, vec3(1.0, 0.165, 0.22), accentLine.mul(0.95));

  material.colorNode = finalColor;

  // Create Mesh
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // 3. Texture Loading (Brushed Metal Specular/Roughness driver)
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.wrapS = 1000; // RepeatWrapping
    tex.wrapT = 1000;
    tex.repeat.set(2, 2);
    material.roughnessMap = tex;
    material.metalnessMap = tex;
    material.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load brushed metal texture map:', err);
  });

  // 4. Lighting design (Accented rim light to prevent DEAD_LIGHTING and highlight metallic surface)
  const localLight = new PointLight('#ff2a38', 1.4, 6.0);
  localLight.position.set(1.5, 1.0, 0.8);
  group.add(localLight);

  // 5. Idle Animation (Subtle light drifting over the card surface)
  const lightTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  lightTimeline.to(localLight.position, {
    x: -1.5,
    y: -0.5,
    duration: 6.0,
    ease: 'sine.inOut'
  });

  // 6. Cleanup Hook
  group.userData = {
    handlers: {},
    cleanup() {
      lightTimeline.kill();
      geometry.dispose();
      material.dispose();
    }
  };

  return group;
}
